 const offerPlan=(plan:WorkspacePlan,chat=false,question=plan.command)=>{if(chat){const messageId=uid();setWs(w=>({...w,messages:[...w.messages,{id:messageId,role:'assistant' as const,content:'Preparé '+plan.operations.length+(plan.operations.length===1?' cambio':' cambios')+' para tu workspace. Revisa la propuesta antes de aplicarla.',provider:'workspace',status:'complete' as const}].slice(-1000)}));setPendingPlan({plan,messageId});setAiInput('')}else{setPendingPlan({plan});setModal({kind:'workspaceAction'})}};
 const executePlan=async()=>{if(!pendingPlan||actionBusy)return;if(conflict){notify('Resuelve el conflicto de guardado antes de aplicar cambios.');return}setActionBusy(true);try{const snapshot=wsRef.current;const savedVersion=await flush(snapshot);if(JSON.stringify(wsRef.current)!==JSON.stringify(snapshot))throw Error('Tu contexto cambió mientras se guardaba. Revisa la propuesta y vuelve a aplicarla.');const fingerprint=JSON.stringify(snapshot);const response=await fetch('/api/ai/actions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({plan:pendingPlan.plan,messageId:pendingPlan.messageId,version:savedVersion,confirmed:true}),signal:AbortSignal.timeout(20000)});const result=await response.json();if(response.status===409)markConflict();if(!response.ok)throw Error(result.error||'No se pudo confirmar el guardado.');if(JSON.stringify(wsRef.current)!==fingerprint){markConflict();throw Error('Los cambios se guardaron, pero hay nuevas ediciones locales. Exporta tu respaldo y actualiza el contexto antes de continuar.')}adoptCloud(result.state,result.version);wsRef.current=result.state;setPendingPlan(null);setModal(null);notify(result.replayed?'Esta operación ya estaba guardada.':'Cambios guardados y registrados')}catch(e:any){notify(e.message||'No se pudo confirmar el guardado.')}finally{setActionBusy(false)}};
