 const promptFromPage=(question:string)=>{const title=question.match(/["“]([^"”]+)["”]/)?.[1];const doc=entries('documents').find(d=>d.title===title);go('copilot');setComposerMode(/^Planifica/.test(question)?'actions':'auto');setAiInput(question);if(doc)setAttachments([{id:uid(),name:doc.title+'.md',type:'md',size:doc.description.length,text:doc.description}])};
