 async function handleFiles(files:FileList|File[]|null){if(!files?.length||readingRef.current)return;if(busy){notify('Espera a que termine la consulta para adjuntar archivos.');return}if(attachmentsRef.current.length+files.length>5){notify('Puedes adjuntar hasta 5 archivos por consulta.');return}readingRef.current=true;setReadingFiles(true);setAttachmentError('');try{const extracted=await readAttachmentBatch(Array.from(files),uid);const result=await storeOriginals(Array.from(files),extracted.attachments);setAttachments(a=>[...a,...result.attachments].slice(0,5));setAttachmentError([...extracted.errors,...result.errors].join(' · '));if(result.attachments.length)notify(result.attachments.length+' archivo(s) guardado(s) y listo(s) para enviar')}finally{readingRef.current=false;setReadingFiles(false);if(fileInputRef.current)fileInputRef.current.value=''}}
 async function fetchResearch(query:string,signal?:AbortSignal){const r=await fetch('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:query.trim().slice(0,180)}),signal});const d:any=await r.json();if(!r.ok)throw Error(d.error||'La búsqueda no se pudo completar.');return {...d,sources:relevantSources(query,d.sources||[]),note:(d.note||'')+' Las coincidencias de términos no verifican el contenido.'}}
 async function runResearch(){if(researchQuery.trim().length<3||researchBusy)return;setResearchBusy(true);setResearchError('');try{const d=await fetchResearch(researchQuery);setResearchSources(d.sources);if(d.unavailable.length)setResearchError('Fuente no disponible: '+d.unavailable.join(', '));if(!d.sources.length)setResearchError('No encontramos resultados para ese tema. Prueba con términos más específicos.')}catch(e:any){setResearchError(e.message)}finally{setResearchBusy(false)}}
