 const supportText=(sources:ResearchSource[],submission?:ChatSubmission)=>[(submission?.files||attachments).map(a=>`ARCHIVO ${a.name}:\n${a.text.slice(0,5000)}`).join('\n\n'),(submission?.links||attachedLinks).length?'ENLACES DE REFERENCIA, CONTENIDO NO LEÍDO: '+(submission?.links||attachedLinks).join(' · '):'',sources.map((a,i)=>`FUENTE [${i+1}] ${a.title} — ${a.url}\nFragmento recuperado: ${a.snippet}`).join('\n')].filter(Boolean).join('\n\n').slice(0,10000);
