 const reportFromMessage=(message:Message)=>{const existing=(ws.reports||[]).find(r=>r.id===message.reportId);if(existing){openReport(existing.id);return}const position=ws.messages.findIndex(m=>m.id===message.id);const question=ws.messages.slice(0,position).reverse().find(m=>m.role==='user')?.content||'Consulta empresarial guardada';const report=buildReport({id:uid(),mode:'copilot',question,response:message.content,sources:message.sources||[],workspace:ws,engine:message.provider||'local'});setWs(w=>log({...w,reports:[report,...(w.reports||[])].slice(0,30),messages:w.messages.map(m=>m.id===message.id?{...m,reportId:report.id}:m)},'Informe creado desde una respuesta guardada'));openReport(report.id)};
