 async function askLocal(question:string,mode:string,reference?:{title:string;text:string;engine?:'document-tool'},forceResearch=false,submission?:ChatSubmission){setBusy(true);setActiveMode(mode);setAiError(null);setTyping('');setOperatorResult('');setOperatorReportId('');setGenerationChars(0);setGenerationStage('Seleccionando memoria empresarial');const controller=new AbortController();abortRef.current=controller;const snapshot=wsRef.current;let sources=researchSources;let full='';const stream=createTypingStream(text=>{if(mode==='copilot')setTyping(text);else setOperatorResult(text)},controller.signal,!ws.preferences.motion);setAiInput('');try{if(searchEnabled||forceResearch){setGenerationStage('Recuperando fuentes públicas');try{const results=await fetchResearch(forceResearch?researchTopic(question):researchQuery.trim()||question,controller.signal);sources=results.sources;setResearchSources(sources);if(!sources.length)notify('No se encontraron fuentes. El informe identificará esta limitación.')}catch(e:any){if(e.name==='AbortError')throw e;sources=[];setResearchSources([]);notify('La búsqueda no pudo completarse. Se utilizará el contexto aportado.')}}const request=businessMessages(snapshot,question,mode,supportText(sources,submission),localAIInfo().profile==='compatible');setGenerationStage(reference?.engine==='document-tool'?'Leyendo campo del archivo':reference?'Consultando referencia de Startupia':'Preparando la respuesta especializada');const result=reference?reference.text:await generateLocalAI(request.messages,text=>{full=text;setGenerationChars(text.length);stream.push(text)},controller.signal,{maxNewTokens:request.options.maxNewTokens});full=finishResponse(result,question,sources.length);const issue=reference?null:responseIssue(full,question);if(issue)throw Error(issue);setGenerationChars(full.length);if(!full.trim()||!usableResponse(full,question)){full='';throw Error('El modelo devolvió una respuesta insuficiente para esta consulta. Prueba una instrucción más concreta o el modo avanzado en un navegador compatible.');}stream.push(full);await stream.drain();if(controller.signal.aborted)throw new DOMException('Generación detenida','AbortError');const report=buildReport({id:uid(),mode,question,response:full,sources,workspace:snapshot,engine:reference?(reference.engine||'startupia-reference'):localAIInfo().model+' · '+localAIInfo().device});setOperatorReportId(report.id);if(mode==='copilot')setWs(w=>log({...w,reports:[report,...(w.reports||[])].slice(0,30),messages:[...w.messages,{id:uid(),role:'assistant' as const,content:full,provider:reference?(reference.engine||'startupia-reference'):'local',status:'complete' as const,sources,reportId:report.id}].slice(-1000)},'Respuesta e informe empresarial generados'));else{setOperatorResult(full);saveReport(report)}}catch(e:any){const stopped=e.name==='AbortError';if(full.trim()&&mode==='copilot')setWs(w=>({...w,messages:[...w.messages,{id:uid(),role:'assistant' as const,content:full,provider:'local',status:stopped?'stopped' as const:'error' as const,sources}].slice(-1000)}));if(mode!=='copilot')setOperatorResult(full);if(!stopped)setAiError({message:e.message||'El motor no pudo terminar. Revisa la conexión y vuelve a intentarlo.',question,mode});else if(mode!=='copilot')setOperatorResult(full);setLocalReady(isLocalAIReady())}finally{stream.close();setTyping('');setBusy(false);setGenerationStage('');abortRef.current=null;inFlight.current=false}}
 function ContextChips(){return (attachments.length||attachedLinks.length||researchSources.length||readingFiles)?<div className="context-chips">{attachments.map(a=><span className="context-file" key={a.id}><Icon name="FileText" size={13}/><span title={a.name}>{a.name}{a.truncated?' · texto parcial':''}</span><button type="button" aria-label={'Quitar '+a.name} onClick={()=>setAttachments(v=>v.filter(x=>x.id!==a.id))}><Icon name="X" size={11}/></button></span>)}{attachedLinks.map((l,i)=><span className="context-file" key={l}><Icon name="Link" size={12}/><span>{new URL(l).hostname}</span><button type="button" aria-label={'Quitar enlace '+(i+1)} onClick={()=>setAttachedLinks(v=>v.filter(x=>x!==l))}><Icon name="X" size={11}/></button></span>)}{researchSources.length>0&&<span className="context-file sources-chip"><button type="button" className="view-sources" onClick={()=>setModal({kind:'research'})}><Icon name="Globe" size={12}/>{researchSources.length} fuentes</button><button type="button" aria-label="Quitar fuentes del contexto" onClick={()=>setResearchSources([])}><Icon name="X" size={11}/></button></span>}{readingFiles&&<span className="context-file"><Icon name="LoaderCircle" className="spinning" size={13}/>Leyendo archivo…</span>}</div>:null}
 function ContextTools({scope='chat'}:{scope?:string}={}){return <div className="context-tools"><div className="attach-control"><button type="button" className={'icon-btn '+(attachMenu===scope?'selected':'')} aria-label="Adjuntar contexto" aria-expanded={attachMenu===scope} aria-haspopup="menu" onClick={()=>setAttachMenu(attachMenu===scope?null:scope)}><Icon name="Plus" size={18}/></button>{attachMenu===scope&&<div className="attachment-menu" role="menu">{[['Paperclip','Subir archivos',()=>fileInputRef.current?.click()],['Link','Agregar enlace',()=>setModal({kind:'link'})],['Files','Mis documentos',()=>setModal({kind:'documentsPicker'})]].map(([icon,label,fn])=><button type="button" key={String(label)} onClick={()=>{setAttachMenu(null);(fn as ()=>void)()}}><Icon name={String(icon)} size={16}/>{String(label)}<Icon name="ChevronRight" size={12}/></button>)}{attachments.length>0&&<button type="button" onClick={()=>{setWs(w=>{const documents=[...(w.records.documents||[])];for(const a of attachments){const entry={...emptyEntry(a.name),id:a.id,description:a.text,tag:'Dato registrado'};const i=documents.findIndex(d=>d.id===a.id);if(i>=0)documents[i]=entry;else documents.push(entry)}return log({...w,records:{...w.records,documents}},'Adjuntos guardados en Documentos')});setAttachMenu(null);notify('Texto de los adjuntos guardado en Documentos')}}><Icon name="Save" size={16}/>Guardar adjuntos<Icon name="ChevronRight" size={12}/></button>}<small>PDF, DOCX, TXT, MD, CSV, JSON · hasta 3 MB. El original se guarda en tu cuenta; el texto se conserva al enviar.</small></div>}</div><button type="button" className={'research-toggle '+(searchEnabled?'active':'')} aria-pressed={searchEnabled} onClick={()=>setSearchEnabled(!searchEnabled)}><Icon name="Globe" size={14}/><span>Investigar</span></button><button type="button" className="icon-btn" aria-label="Buscar fuentes públicas" onClick={()=>{setResearchQuery((operatorInput||aiInput).slice(0,180));setModal({kind:'research'})}}><Icon name="Search" size={15}/></button><select aria-label="Motor de inteligencia" value={model} onChange={e=>setModel(e.target.value as "local"|"openai")} disabled={busy}><option value="openai">Startupia AI{!providers.openai?" · configuración pendiente":""}</option><option value="local">Motor en este dispositivo</option></select><span className="engine-label"><span className={(model==='local'?localReady:providers.openai)?'live-dot':'pending-dot'}/>{model==='local'?(localReady?'IA local':'Startupia AI'):'Startupia AI'}</span></div>}
 async function ask(question:string,mode='copilot',forceLocal=false,existingSubmission?:ChatSubmission){if(inFlight.current||readingRef.current||readingFiles)return;if(!ready){notify('Espera a que se cargue tu workspace.');return}setAiError(null);let submission=existingSubmission;if(!question.trim()&&!attachments.length&&!attachedLinks.length)return;if(mode==='copilot'&&!submission){try{const prepared=prepareSubmission(wsRef.current,question,attachments,attachedLinks);wsRef.current=prepared.workspace;setWs(prepared.workspace);submission=prepared.submission;question=submission.question;setAiInput('');setAttachments([]);setAttachedLinks([]);setAttachmentError('')}catch(e:any){notify(e.message);return}}retrySubmission.current=submission;try{const plan=planCommand(wsRef.current,question);if(plan){offerPlan(plan,mode==='copilot',question);return}}catch(e:any){if(mode==='copilot'){setWs(w=>({...w,messages:[...w.messages,{id:uid(),role:'assistant' as const,content:e.message,provider:'workspace',status:'complete' as const}].slice(-1000)}))}else notify(e.message);return}if(question.length>8000){notify('Divide esta consulta en partes de menos de 8.000 caracteres.');return}if(model==='openai'&&!forceLocal){inFlight.current=true;await askRemote(question.trim(),mode);return}if(isResearchRequest(question)&&!isLocalAIReady()){inFlight.current=true;await askResearchOnly(question,mode);return}const documentFact=mode==='copilot'?documentReference(question,submission?.files||attachments):null;const reference=documentFact||(mode==='copilot'&&!searchEnabled&&!(submission?.files.length||attachments.length)&&!(submission?.links.length||attachedLinks.length)?startupReference(question):null);if(reference){inFlight.current=true;await askLocal(question.trim(),mode,reference,false,submission);return}if(!isLocalAIReady()&&!forceLocal){setLocalReady(false);pendingAsk.current={question,mode,submission};setModal({kind:'localAI'});return}setLocalReady(isLocalAIReady());inFlight.current=true;if(composerMode==='actions'){await askActionPlanner(question.trim(),mode,submission);return}await askLocal(question.trim(),mode,undefined,isResearchRequest(question),submission)}
 async function askRemote(question:string,mode:string){setBusy(true);setActiveMode(mode);setAiError(null);setTyping('');setOperatorResult('');setOperatorReportId('');setGenerationChars(0);setGenerationStage('Guardando el contexto para Startupia AI');const controller=new AbortController();abortRef.current=controller;let text='',sources:ResearchSource[]=[];let completed:any=null;try{const snapshot=wsRef.current;await flush(snapshot);if(JSON.stringify(wsRef.current)!==JSON.stringify(snapshot))throw Error('El contexto cambió mientras se guardaba. Revisa los cambios y vuelve a consultar.');if(controller.signal.aborted)throw new DOMException('Consulta detenida','AbortError');setGenerationStage(composerMode==='actions'?'Preparando una propuesta verificable':'Consultando Startupia AI');const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json',Accept:composerMode==='actions'?'application/json':'text/event-stream'},body:JSON.stringify({question,mode,actions:composerMode==='actions',research:searchEnabled||isResearchRequest(question)}),signal:controller.signal});if(!r.ok){const d=await r.json();throw Error(d.error||'La consulta no se pudo completar.')}if(r.headers.get('content-type')?.includes('text/event-stream')){if(!r.body)throw Error('La respuesta llegó vacía.');for await(const event of responseEvents(r.body)){if(event.type==='context'){sources=event.sources||[];setResearchSources(sources)}if(event.type==='delta'){text+=event.text||'';setGenerationChars(text.length);if(mode==='copilot')setTyping(text);else setOperatorResult(text)}if(event.type==='error')throw Error(event.error||'La respuesta se interrumpió.');if(event.type==='completed')completed=event;}if(!completed)throw Error('La respuesta se interrumpió antes de completarse.')}else{completed=await r.json();text=completed.text||'';sources=completed.sources||[];}if(controller.signal.aborted)throw new DOMException('Consulta detenida','AbortError');setUsage(u=>({...u,used:u.used+1}));if(completed.proposal){offerPlan(completed.proposal,mode==='copilot',question);return}const report=completed.report as OperatorReport;if(!text.trim()||!report||!validReports([report]))throw Error('La IA no devolvió una respuesta completa verificable.');setOperatorReportId(report.id);setResearchSources(sources);if(mode==='copilot')setWs(w=>log({...w,reports:[report,...(w.reports||[])].slice(0,30),messages:[...w.messages,{id:uid(),role:'assistant' as const,content:text,provider:'openai',status:'complete' as const,sources,reportId:report.id}].slice(-1000)},'Respuesta e informe de Startupia AI'));else{setOperatorResult(text);saveReport(report)}}catch(e:any){const stopped=e.name==='AbortError';if(text.trim()&&mode==='copilot')setWs(w=>({...w,messages:[...w.messages,{id:uid(),role:'assistant' as const,content:text,provider:'openai',status:stopped?'stopped' as const:'error' as const,sources}].slice(-1000)}));if(!stopped)setAiError({message:e.message||'La consulta no pudo completarse.',question,mode});else notify('Consulta detenida. El contenido parcial no se considera un informe completo.');void fetch('/api/ai/status').then(r=>r.json()).then(d=>{if(d.usage)setUsage(d.usage)}).catch(()=>{})}finally{setTyping('');setBusy(false);setGenerationStage('');abortRef.current=null;inFlight.current=false}}
 async function askResearchOnly(question:string,mode:string){setBusy(true);setActiveMode(mode);setGenerationStage('Recuperando fuentes públicas');setAiError(null);setOperatorReportId('');setOperatorResult('');setTyping('');setGenerationChars(0);setAiInput('');const controller=new AbortController();abortRef.current=controller;const stream=createTypingStream(text=>mode==='copilot'?setTyping(text):setOperatorResult(text),controller.signal,!ws.preferences.motion);try{const topic=researchTopic(question);setResearchQuery(topic);const result=await fetchResearch(topic,controller.signal);setResearchSources(result.sources);const response=researchBrief(topic,result.sources,result.unavailable);setGenerationStage('Presentando fuentes recuperadas');setGenerationChars(response.length);stream.push(response);await stream.drain();if(controller.signal.aborted)throw new DOMException('Búsqueda detenida','AbortError');const report=buildReport({id:uid(),mode,question,response,sources:result.sources,workspace:wsRef.current,engine:'research-tool'});setOperatorReportId(report.id);if(mode==='copilot')setWs(w=>log({...w,reports:[report,...(w.reports||[])].slice(0,30),messages:[...w.messages,{id:uid(),role:'assistant' as const,content:response,provider:'research-tool',status:'complete' as const,sources:result.sources,reportId:report.id}].slice(-1000)},'Investigación con fuentes guardada'));else{setOperatorResult(response);saveReport(report)}}catch(e:any){if(e.name!=='AbortError')setAiError({message:e.message,question,mode})}finally{stream.close();setTyping('');setBusy(false);setGenerationStage('');abortRef.current=null;inFlight.current=false}}
 async function askActionPlanner(question:string,mode='copilot',submission?:ChatSubmission){setBusy(true);setActiveMode(mode);setAiError(null);setGenerationStage('Preparando cambios estructurados');setGenerationChars(0);const controller=new AbortController();abortRef.current=controller;try{const text=await generateLocalAI(modelActionMessages(wsRef.current,question,(submission?.files||attachments).map(a=>a.name+'\n'+a.text).join('\n\n'),localAIInfo().profile==='compatible'?2400:7500),text=>setGenerationChars(text.length),controller.signal,{maxNewTokens:localAIInfo().profile==='compatible'?320:900});const plan=decodeModelPlan(wsRef.current,question,text);offerPlan(plan,mode==='copilot',question)}catch(e:any){if(e.name!=='AbortError')setAiError({message:e.message,question,mode})}finally{setBusy(false);setGenerationStage('');abortRef.current=null;inFlight.current=false;setLocalReady(isLocalAIReady())}}
 const planReport=(report:OperatorReport)=>{try{const documentId='report-'+report.id;const marker='Informe: '+report.id;const operations:Parameters<typeof makePlan>[3]=report.tasks.filter(t=>!entries('tasks').some(e=>e.title===t.title&&e.description.endsWith(marker))).map(t=>({type:'create',kind:'tasks',entry:{...emptyEntry(t.title),description:t.description+'\n\n'+marker,tag:report.engine==='research-tool'?'Propuesta por revisar':'Propuesta de IA',target:1}}));if(!entries('documents').some(e=>e.id===documentId)){const blocks=markdownBlocks(reportMarkdown(report),uid);operations.unshift({type:'create',kind:'documents',entry:{...emptyEntry(report.title),id:documentId,description:documentText(blocks),blocks,icon:'route',cover:'navy',tag:'Informe empresarial'}})}if(!operations.length){notify('Este informe y sus tareas ya están en tu workspace.');return}offerPlan(makePlan(ws,'Llevar informe al workspace','Informe y próximos pasos',operations,'workflow',['Las tareas son propuestas basadas en el informe. No representan resultados ya obtenidos.']))}catch(e:any){notify(e.message)}};
 const createFromAI=(text:string,kind='notes')=>{add(kind,{...emptyEntry('Resultado · '+titles[page]),description:text,tag:'Generado por IA'});notify('Resultado guardado en '+titles[kind])};
 const action=(label:string,fn:()=>void,icon='Plus',primary=false,disabled=false)=><button disabled={disabled} className={primary?'btn primary':'btn'} onClick={fn}><Icon name={icon} size={16}/>{label}</button>;
